<link rel="stylesheet" href="../assets/css/integ-borrower/<?= e($design) ?>.css"><link rel="stylesheet" href="../assets/css/borrower-flow.css"><link rel="stylesheet" href="../assets/css/borrower-portal.css"><link rel="stylesheet" href="../assets/css/portal-integration.css"><link rel="stylesheet" href="<?= e(base_url()) ?>/assets/css/local-fonts.css"></head><body class="uw-borrower-portal"><div class="<?= $dashboard?'dashboard-layout':'client-layout' ?>"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-icon"><img src="../assets/logo/utangwiselogo.png" alt="Utang Wise"></div><div class="brand-text"><h2>UTANG WISE</h2><span>LENDING MADE SIMPLE</span></div></div><nav class="sidebar-menu"><?php foreach(['client-dashboard'=>['home','Dashboard'],'profile'=>['person','Profile'],'my-loans'=>['description','My Loans'],'request-loan'=>['add_circle','Request Loan'],'payments'=>['credit_card','Payments'],'payment-extension'=>['calendar_month','Payment Extension'],'payment-history'=>['history','Payment History'],'signed-agreement'=>['draw','Agreements']] as $route=>$item): ?><a class="menu-item <?= $route===$active?'active':'' ?>" href="<?= e($route) ?>.php"><span class="material-symbols-outlined" aria-hidden="true"><?= e($item[0]) ?></span><span><?= e($item[1]) ?></span></a><?php endforeach; ?></nav><div class="sidebar-divider"></div><?php borrower_logout_button(); ?></aside><button type="button" class="sidebar-overlay" id="portalOverlay" aria-label="Close navigation" hidden></button><main class="<?= $dashboard?'main-area':'main-content' ?>"><header class="topbar"><div class="topbar-left"><button type="button" class="mobile-menu-btn" id="portalMenu" aria-label="Toggle menu" aria-controls="sidebar" aria-expanded="false"><span class="material-symbols-outlined">menu</span></button><div class="topbar-page-title"><span>Welcome back!</span><h2><?= e($title) ?></h2></div></div><div class="top-user user-area"><details class="portal-notifications"><summary aria-label="Notifications"><span class="material-symbols-outlined" aria-hidden="true">notifications</span><span><?= count($items=borrower_notices($u['user_id'])) ?></span></summary><div><h3>Notifications</h3><?php if(!$items): ?><p>No unread reminders.</p><?php endif; foreach($items as $item): ?><form method="post" action="../controllers/borrower-notifications.php"><?php csrf(); ?><input type="hidden" name="event_key" value="<?= e($item['key']) ?>"><p><?= e($item['text']) ?></p><button class="portal-button">Mark as read</button></form><?php endforeach; ?><a href="payments.php">View payments</a></div></details><a class="topbar-profile" href="profile.php"><span class="top-avatar user-avatar"><?php if(document_exists($u['user_id'],'profile_photo')): ?><img class="topbar-profile-photo avatar-photo" src="../ajax/borrower_document.php?kind=profile_photo" alt="Your profile photo"><?php else: ?><span class="material-symbols-outlined" aria-hidden="true">person</span><?php endif; ?></span><span class="top-user-text user-text"><strong><?= e($u['user_fn'].' '.$u['user_ln']) ?></strong><small>Borrower</small></span></a></div></header><div class="<?= $dashboard?'dashboard-body':'page-content' ?>"><section class="dashboard-content"><div class="page-heading welcome-section"><h1><?= e($title) ?></h1></div><?php notice();}
function portal_end(){?></section></div></main></div><script src="../assets/js/borrower-portal.js" defer></script><?php uw_success_assets(); ?></body></html><?php }
function portal_history_table($rows){?><div class="table-wrapper"><table><thead><tr><th>Payment ID</th><th>Date</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>PAY-<?= (int)$r['payment_id'] ?></td><td><?= e($r['payment_date']) ?></td><td><?= money($r['amount']) ?></td><td><?= e($r['method']) ?></td><td><?= e($r['payment_status']) ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5">No payments recorded yet.</td></tr><?php endif; ?></tbody></table></div><?php }
